def adopt(source,cid,status,scope):
    c=copy.deepcopy(next(x for x in read(R/source) if x['claim_id']==cid))
    original=c['statement_sha256'];c['statement_sha256']=hashlib.sha256(c['exact_statement'].encode()).hexdigest()
    c['review_records'].append({'reviewer':'A087','verdict':status,'scope':scope,'source_run':rid,'source':'PROOF.md; out/CHECK.json','method':'Independent physical Walsh/edge and own-history Bellman reconstruction; all-dimensional analytic proof, no source repair','original_recorded_statement_sha256':original,'snapshot_sha256':sha(R/source)})
    c['status']=status;claims.append(c);return c
